        complete = status == meta["complete"]
        rid = rec.get(meta["id"], "")
        sub = rec.get(meta["submitted"], "")
        instant = parse_instant(sub, meta.get("submitted_format", "iso"), meta.get("utc_offset")) if sub else datetime.min
        dur_cell = rec.get(meta["duration"], "")
        dur = parse_duration(dur_cell, meta.get("duration_format", "seconds")) if dur_cell else None
        lp_cell = rec.get(meta["last_page"], "")
        last_page = to_int(lp_cell) if lp_cell else 0
        rows.append({"v": v, "rec": rec, "id": rid, "complete": complete, "t": instant,
